 21	/**
 22	 * A native whose builtinPrimitive string names a static Java method of the
 23	 * package com.sun.fortress.nativeHelpers, "com.sun.fortress.nativeHelpers.Class.method",
 24	 * in place of a glue class.  Among the class's public static methods of that
 25	 * name it takes the one whose Java parameter and result types carry the
 26	 * declaration's types; a functional method's self, and a dotted method's self,
 27	 * go first.  It calls the method by reflection, each argument unboxed and the
 28	 * result boxed at the declared result type.  A helper's raise of an exception
 29	 * class of the compiled path, "fortress.<Api>$<Name>", becomes the raise of the
 30	 * library's own exception object <Name>, as Int.overflow() raises IntegerOverflow.
 31	 */
 32	public class StaticNativeApp extends NativeMeth {
 33	    public static final String HELPERS = "com.sun.fortress.nativeHelpers.";
 34	
 35	    /** Does s name a helper (a static method of nativeHelpers), not a glue class? */
 36	    public static boolean isHelperString(String s) {
 37	        return s.startsWith(HELPERS);
 38	    }
 39	
 40	    private final Method m;
 41	    private final Class<?>[] ps;
 42	    private final String result;     // the declared result type's name
 43	    private final int selfAt;        // index of self among the declared parameters, or -1
 44	    private int arity;
 45	
 46	    /** The Java type that carries a value of the named Fortress type, or null. */
 47	    static Class<?> javaFor(String t) {
 48	        if (t == null) return null;
 49	        if (t.equals("ZZ32") || t.equals("NN32") || t.equals("Char")) return int.class;
 50	        if (t.equals("ZZ64") || t.equals("NN64")) return long.class;
 51	        if (t.equals("RR64")) return double.class;
 52	        if (t.equals("RR32")) return float.class;
 53	        if (t.equals("Boolean")) return boolean.class;
 54	        if (t.equals("String") || t.equals("FlatString") || t.equals("JavaString")) return String.class;
 55	        if (t.equals("ZZ")) return BigInteger.class;
 56	        if (t.equals("()")) return void.class;
 57	        return null;
 58	    }
 59	
 60	    static String typeName(TypeOrPattern t) {
 61	        if (t instanceof TupleType && ((TupleType) t).getElements().isEmpty()) return "()";
 62	        if (t instanceof NamedType) return ((NamedType) t).getName().getText();
 63	        return null;
 64	    }
 65	
 66	    static boolean hasResultType(Applicable defn) {
 67	        Option<Type> r = NodeUtil.getReturnType(defn);
 68	        return r != null && r.isSome();
 69	    }
 70	
 71	    /** The name of the declared result type, or null. */
 72	    static String declaredResult(Applicable defn) {
 73	        return hasResultType(defn) ? typeName(NodeUtil.getReturnType(defn).unwrap()) : null;
 74	    }
 75	
 76	    static boolean carried(Class<?> c) {
 77	        return c == int.class || c == long.class || c == double.class || c == float.class
 78	            || c == boolean.class || c == String.class || c == BigInteger.class;
 79	    }
 80	
 81	    /**
 82	     * The helper that the string s names for the declaration defn, or an error message.  Among the
 83	     * class's public static methods of that name, it takes the one whose parameters are the
 84	     * declaration's, self first where the declaration has one (a functional method), or one more
 85	     * in front for a dotted method's self, at the Java types that carry the declared types.
 86	     */
 87	    static Object find(String s, Applicable defn) {
 88	        int dot = s.lastIndexOf('.');
 89	        String cls = s.substring(0, dot), name = s.substring(dot + 1);
 90	        Class<?> c;
 91	        try { c = Class.forName(cls); }
 92	        catch (ClassNotFoundException e) { return "Native helper class " + cls + " not found."; }
 93	        List<Method> named = new ArrayList<Method>();
 94	        for (Method x : c.getMethods())
 95	            if (x.getName().equals(name) && Modifier.isStatic(x.getModifiers())) named.add(x);
 96	        if (named.isEmpty()) return "Native helper " + s + " names no static method of " + cls + ".";
 97	        List<Class<?>> want = new ArrayList<Class<?>>();
 98	        boolean hasSelf = false;
 99	        for (Param p : NodeUtil.getParams(defn)) {
100	            String pn = p.getName().getText();
101	            if (pn.equals("self")) { hasSelf = true; continue; }
102	            Class<?> j = javaFor(p.getIdType().isSome() ? typeName(p.getIdType().unwrap()) : null);
103	            if (j == null || j == void.class)
104	                return "Native helper " + s + ": no Java type carries the declared type of parameter " + pn + ".";
105	            want.add(j);
106	        }
107	        Class<?> res = null;    // a declaration without a result type is refused by NativeApp.init
108	        if (hasResultType(defn)) {
109	            res = javaFor(declaredResult(defn));
110	            if (res == null) return "Native helper " + s + ": no Java type carries the declared result type.";
111	        }
112	        List<Method> fits = new ArrayList<Method>();
113	        for (Method x : named) {
114	            Class<?>[] xs = x.getParameterTypes();
115	            int off = xs.length - want.size();          // 1: self first
116	            if (off < 0 || off > 1 || (hasSelf && off != 1)) continue;
117	            boolean ok = (res == null || x.getReturnType() == res)
118	                         && (x.getReturnType() == void.class || carried(x.getReturnType()));
119	            for (int i = 0; ok && i < xs.length; i++) {
120	                if (!carried(xs[i])) ok = false;
121	                else if (i >= off && xs[i] != want.get(i - off)) ok = false;
122	            }
123	            if (ok) fits.add(x);
124	        }
125	        if (fits.size() == 1) return fits.get(0);
126	        if (fits.isEmpty()) return "Native helper " + s + " has no overload that fits the declaration's types.";
127	        return "Native helper " + s + " has " + fits.size() + " overloads that fit the declaration's types.";
128	    }
129	
130	    StaticNativeApp(Method m, Applicable defn) {
131	        this.m = m;
132	        this.ps = m.getParameterTypes();
133	        this.result = declaredResult(defn);
134	        int at = -1, i = 0;
135	        for (Param p : NodeUtil.getParams(defn)) { if (p.getName().getText().equals("self")) at = i; i++; }
136	        this.selfAt = at;
137	    }
