139	    public int getArity() { return arity; }
140	
141	    protected void init(Applicable app, boolean isFunctionalMethod) {
142	        arity = NodeUtil.getParams(app).size() - (isFunctionalMethod ? 1 : 0);
143	        super.init(app, isFunctionalMethod);
144	    }
