162	    private FValue call(List<FValue> args) {
163	        if (args.size() != ps.length) return error("Native " + m + " given " + args.size() + " arguments");
164	        Object[] xs = new Object[ps.length];
165	        for (int i = 0; i < ps.length; i++) xs[i] = unbox(ps[i], args.get(i));
166	        try {
167	            return box(m.getReturnType(), result, m.invoke(null, xs));
168	        }
169	        catch (InvocationTargetException e) {
170	            Throwable t = e.getCause();
171	            FortressError f = raised(t);
172	            if (f != null) throw f;
173	            if (t instanceof RuntimeException) throw (RuntimeException) t;
174	            if (t instanceof Error) throw (Error) t;
175	            return error(t.toString());
176	        }
177	        catch (IllegalAccessException e) {
178	            return error(e.toString());
179	        }
180	    }
